# -*- coding: utf-8 -*-
"""Chapter 1 - Part C: Practice questions Q26-Q50."""

CH1_Q2 = [
("q", {"n": 26, "level": "Difficult", "concept": "City-grid application (T11)",
 "stem": "In a city, streets run in two perpendicular directions, 200 m apart. Intersections are labelled (row, column). An auto rickshaw goes from intersection (1, 1) to intersection (4, 3). (i) What is the shortest distance it can travel moving only along streets? (ii) What is the straight-line (as-the-crow-flies) distance? (iii) How much shorter is the direct route?",
 "steps": [
  "Given: grid spacing 200 m, start (1, 1), end (4, 3). Needed: street distance, direct distance, saving.",
  "Moving along streets from row 1 to row 4 needs 3 steps; from column 1 to column 3 needs 2 steps.",
  "Shortest street path = 3 + 2 = 5 steps = 5 x 200 = 1000 m.",
  "Direct distance uses the distance formula with coordinate gap 3 rows and 2 columns: \u221a(3\u00b2 + 2\u00b2) x 200 = \u221a13 x 200 approx 3.606 x 200 approx 721 m.",
  "Saving = 1000 - 200\u221a13 approx 1000 - 721 = 279 m (about 28 percent).",
  "Note the concept: along-streets distance adds the gaps; direct distance applies Pythagoras to the same gaps.",
 ],
 "hinglish": "City grid hi bada coordinate plane hai - bas unit 200 m hai. Galiyon mein chalna hai toh horizontal + vertical steps JODO (3 + 2 = 5 blocks = 1000 m). Seedha udna hai toh Pythagoras lagao: \u221a(9 + 4) = \u221a13 blocks. Difference dekho - seedha rasta karib 280 m bachata hai. Yahi idea PDF ke athletics track aur map questions mein bhi chalta hai: grid distance vs straight distance.",
 "answer": "(i) 1000 m   (ii) 200\u221a13 approx 721 m   (iii) approx 279 m shorter"}),

("q", {"n": 27, "level": "Difficult", "concept": "Rhombus from coordinates (T6)",
 "stem": "The points (0, 5), (-3, 0), (0, -5) and (3, 0) are the corners of a quadrilateral taken in order. Show that it is a rhombus and find the lengths of its diagonals and its area.",
 "steps": [
  "Given: four symmetric points. Needed: prove rhombus, diagonals, area.",
  "Side from (0, 5) to (-3, 0): \u221a(3\u00b2 + 5\u00b2) = \u221a34.",
  "Side from (-3, 0) to (0, -5): \u221a(3\u00b2 + 5\u00b2) = \u221a34. By the same computation each of the remaining two sides is \u221a(3\u00b2 + 5\u00b2) = \u221a34.",
  "All four sides are equal to \u221a34, so the quadrilateral is a rhombus (a parallelogram with equal sides; symmetry about both axes guarantees the parallelogram behaviour, and can be double-checked: opposite sides are translations of each other).",
  "Diagonal 1 joins (0, 5) to (0, -5): vertical, length 10.",
  "Diagonal 2 joins (-3, 0) to (3, 0): horizontal, length 6.",
  "Area of a rhombus = (1/2) x product of diagonals = (1/2) x 10 x 6 = 30 square units.",
 ],
 "hinglish": "Chaaron sides \u221a34 - rhombus pakka. Diagonals yahan axis par hi baithi hain, isliye unki length seedhi mili: 10 aur 6. Rhombus ka area = (1/2) d1 d2 = 30 - ye formula yaad rakho, square/rectangle ke bhai ki tarah. Ye PDF ke Ch 6 se connect hota hai jahan rhombus-area questions hain, par classification toh pure Chapter 1 ka khel hai (distance formula).",
 "answer": "All sides \u221a34, so it is a rhombus; diagonals 10 and 6; area = 30 square units."}),

("q", {"n": 28, "level": "Difficult", "concept": "Algebraic distance (T4/T14)",
 "stem": "Find the distance between the points (a + b, a - b) and (a - b, a + b), where a and b are real numbers with b not equal to 0. The answer must be in terms of b.",
 "steps": [
  "Given: two symbolic points. Needed: distance in terms of b.",
  "x-difference: (a + b) - (a - b) = 2b.",
  "y-difference: (a - b) - (a + b) = -2b.",
  "Distance = \u221a((2b)\u00b2 + (-2b)\u00b2) = \u221a(4b\u00b2 + 4b\u00b2) = \u221a(8b\u00b2).",
  "Simplify: \u221a(8b\u00b2) = \u221a8 x \u221a(b\u00b2) = 2\u221a2 x |b|.",
  "Since b is not zero, for positive b this is 2\u221a2 b. The cleanest exact answer is 2\u221a2 |b|; note that a cancels out completely - the distance does not depend on a at all.",
 ],
 "why": ["Notice how the a-terms cancel inside both differences. Spotting cancellations before squaring is a mark of an algebra-fluent student."],
 "hinglish": "Symbolic distance question - numbers ki jagah letters, darne ki zaroorat nahi. Difference lo, a dono jagah cancel ho gaya, bacha 2b aur -2b. Square ke baad 8b\u00b2, root se 2\u221a2 |b|. Bar (absolute value) isliye kyunki distance kabhi negative nahi hoti. Interesting observation: answer a par depend hi nahi karta - dono points a se same doori par slide karte hain, unke beech ka gap sirf b se banta hai.",
 "answer": "Distance = \u221a(8b\u00b2) = 2\u221a2 |b| (independent of a)."}),

("q", {"n": 29, "level": "Difficult", "concept": "Equidistant locus (T5/T14)",
 "stem": "A point P(x, y) moves so that its distance from A(3, 4) always equals its distance from B(-1, 6). Show that x and y must satisfy the relation y = 2x + 3, and verify that the point (0, 3) obeys it.",
 "steps": [
  "Given: PA = PB for a moving point. Needed: the relation between x and y.",
  "Write squared distances (roots dropped on both sides - legal since both sides are non-negative).",
  "PA\u00b2 = (x - 3)\u00b2 + (y - 4)\u00b2 = x\u00b2 - 6x + 9 + y\u00b2 - 8y + 16.",
  "PB\u00b2 = (x + 1)\u00b2 + (y - 6)\u00b2 = x\u00b2 + 2x + 1 + y\u00b2 - 12y + 36.",
  "Set PA\u00b2 = PB\u00b2: x\u00b2 - 6x + 9 + y\u00b2 - 8y + 16 = x\u00b2 + 2x + 1 + y\u00b2 - 12y + 36.",
  "Cancel x\u00b2 and y\u00b2 from both sides: -6x - 8y + 25 = 2x - 12y + 37.",
  "Move everything to one side: -8x + 4y - 12 = 0, that is 4y = 8x + 12, giving y = 2x + 3.",
  "Verify (0, 3): PA = \u221a((0 - 3)\u00b2 + (3 - 4)\u00b2) = \u221a(9 + 1) = \u221a10. PB = \u221a((0 + 1)\u00b2 + (3 - 6)\u00b2) = \u221a(1 + 9) = \u221a10. Equal - the point obeys the condition.",
 ],
 "hinglish": "Ye Chapter 1 ka sabse powerful idea hai: distance ki equality ek RELATION bana deti hai. Square karke x\u00b2 aur y\u00b2 cancel kar do - jo bacha wo straight line hai, y = 2x + 3. Is line ke har point dono A aur B se barabar door hai (isko perpendicular bisector kehte hain - Class 11 mein formally aayega). Verification: (0, 3) se dono distances \u221a10. Jab bhi 'equidistant from two points' dikhe, yahi square-and-cancel recipe chalao.",
 "answer": "PA = PB forces y = 2x + 3; verified at (0, 3) where PA = PB = \u221a10."}),

("q", {"n": 30, "level": "Difficult", "concept": "Circle membership with bigger radius (T10)",
 "stem": "Consider the circle with centre the origin and radius 13. (i) Verify that (5, 12), (12, 5), (-12, 5) and (0, 13) all lie on the circle. (ii) Determine whether (6, 12) and (4, 12) lie inside, on, or outside it.",
 "steps": [
  "Given: circle x\u00b2 + y\u00b2 = 169. Needed: classify six points.",
  "(5, 12): 25 + 144 = 169, so on the circle (the 5-12-13 triple).",
  "(12, 5): 144 + 25 = 169, on the circle (same triple, swapped).",
  "(-12, 5): 144 + 25 = 169, on the circle (signs vanish on squaring).",
  "(0, 13): 0 + 169 = 169, on the circle (topmost point).",
  "(6, 12): 36 + 144 = 180 which is greater than 169, so OUTSIDE the circle.",
  "(4, 12): 16 + 144 = 160 which is less than 169, so INSIDE the circle.",
 ],
 "why": ["The 5-12-13 triple is the second most useful triple after 3-4-5; radius 13 questions are built around it."],
 "hinglish": "Radius 13 = 5-12-13 triple ka ghar. Chaaron points check karo - sab 169 de rahe hain, sab circle par. Phir (6, 12) aur (4, 12) ka fun part: 180 > 168... nahi, 180 > 169 toh bahar; 160 < 169 toh andar. Dekho kamaal: (6, 12) aur (4, 12) dono lagbhag same jagah hain, par ek bahar aur ek andar! Circle ki seedhi borderline - yahi precision Chapter 1 sikhata hai.",
 "answer": "All four triple points lie on the circle; (6, 12) is outside; (4, 12) is inside."}),

("q", {"n": 31, "level": "High", "concept": "Trisection points (T8)",
 "stem": "P and Q are the points of trisection of the segment AB, with P closer to A and Q closer to B, where A(4, 7) and B(16, -2). Find P and Q. Then verify that the midpoint of PQ coincides with the midpoint of AB.",
 "steps": [
  "Given: A(4, 7), B(16, -2), trisection needed. Needed: P, Q, and the midpoint check.",
  "Step size: one third of the way from A to B means adding one third of each gap. Gap in x: 16 - 4 = 12; gap in y: -2 - 7 = -9.",
  "One third of the gaps: 12/3 = 4 and -9/3 = -3.",
  "P (closer to A) = A + one step = (4 + 4, 7 - 3) = (8, 4).",
  "Q = A + two steps = (4 + 8, 7 - 6) = (12, 1). Equivalently Q = B - one step = (16 - 4, -2 + 3) = (12, 1). Both give the same.",
  "Midpoint of P and Q = ((8 + 12)/2, (4 + 1)/2) = (10, 2.5).",
  "Midpoint of A and B = ((4 + 16)/2, (7 - 2)/2) = (10, 2.5). They coincide - the check passes.",
 ],
 "why": ["The middle of the two trisectors is always the midpoint of the whole segment - a beautiful structural fact worth remembering for instant verification."],
 "hinglish": "Trisection matlab segment ko 3 barabar tukdon mein kaatna. Fundaa simple: total gap ko 3 se divide karo, wo ek 'step' hai. P = A + ek step, Q = A + do step. Yahan steps (4, -3) the. Aur jo self-check diya na - PQ ka midpoint hamesha AB ke midpoint ke barabar hota hai - ye free verification hai, exam mein zaroor lagao. (10, 2.5) = (10, 2.5), perfect match.",
 "answer": "P(8, 4), Q(12, 1); both midpoints equal (10, 2.5), verification passes."}),

("q", {"n": 32, "level": "High", "concept": "Missing rectangle vertex (T6/T8)",
 "stem": "Three vertices of a rectangle are A(1, 2), B(5, 2) and C(5, 7). Find the fourth vertex D, and verify the rectangle property that its diagonals are equal.",
 "steps": [
  "Given: three consecutive vertices. Needed: D and the diagonal check.",
  "AB is horizontal (y = 2 for both) with length 4; BC is vertical (x = 5 for both) with length 5.",
  "In a rectangle the fourth side DA must be vertical (above A) and CD horizontal - so D must sit directly above A at the same height as C.",
  "Directly above A(1, 2) means x = 1; at the same height as C means y = 7. So D = (1, 7).",
  "Verify with side lengths: DA from (1, 7) to (1, 2) has length 5, CD from (5, 7) to (1, 7) has length 4 - matching the opposite sides.",
  "Diagonal AC = \u221a((5 - 1)\u00b2 + (7 - 2)\u00b2) = \u221a(16 + 25) = \u221a41.",
  "Diagonal BD = \u221a((1 - 5)\u00b2 + (7 - 2)\u00b2) = \u221a(16 + 25) = \u221a41. Equal, so the rectangle property holds.",
 ],
 "hinglish": "Rectangle ka chautha vertex pattern se milta hai: A ke seedha upar, C ke level par. x = 1 (A jaisa), y = 7 (C jaisa). Phir property check - diagonals barabar? Dono \u221a41. Yahan \u221a41 ko simplify nahi kar sakte (41 prime hai), toh root form hi final hai. Notice karo: har rectangle mein diagonals barabar hote hain - ye test humne parallelogram question (Q23) mein bhi use kiya tha, wahan fail hua tha, yahan pass.",
 "answer": "D = (1, 7); diagonals AC = BD = \u221a41, confirming the rectangle."}),

("q", {"n": 33, "level": "High", "concept": "Area of right triangle from coordinates (T12)",
 "stem": "A triangle has vertices O(0, 0), A(8, 0) and B(0, 6). Show that it is right-angled, find its hypotenuse, and compute its area and perimeter.",
 "steps": [
  "Given: three vertices, two of them on the axes. Needed: right angle, hypotenuse, area, perimeter.",
  "OA lies along the x-axis: length 8. OB lies along the y-axis: length 6.",
  "The x-axis and y-axis are perpendicular, and OA, OB lie along them, so the angle at O is 90 degrees.",
  "Hypotenuse AB = \u221a(8\u00b2 + 6\u00b2) = \u221a(64 + 36) = \u221a100 = 10 (the 6-8-10 triple).",
  "Area = (1/2) x OA x OB = (1/2) x 8 x 6 = 24 square units.",
  "Perimeter = 8 + 6 + 10 = 24 units. A charming coincidence: area 24 and perimeter 24.",
 ],
 "hinglish": "Jab triangle ke do sides axes par baithe hon, right angle free mein milta hai - axis parallel hi perpendicular hote hain. Phir 8-6-10 triple se hypotenuse 10. Area = 24, perimeter bhi 24 - dono number same! Aisi coincidences questions mein jaan-bujh ke rakhi jaati hain, toh apne practice questions mein bhi aisi numbers chuno toh checking easy hoti hai.",
 "answer": "Right angle at O; hypotenuse AB = 10; area = 24 sq units; perimeter = 24 units."}),

("q", {"n": 34, "level": "High", "concept": "Square from its diagonal (T14)",
 "stem": "Two opposite corners of a square are P(-3, 2) and R(5, -4). Find the length of the diagonal, the side of the square, its area, and the coordinates of the other two corners.",
 "steps": [
  "Given: diagonal endpoints of a square. Needed: diagonal, side, area, remaining vertices.",
  "Diagonal PR = \u221a((5 - (-3))\u00b2 + (-4 - 2)\u00b2) = \u221a(8\u00b2 + (-6)\u00b2) = \u221a(64 + 36) = \u221a100 = 10.",
  "For a square of side s, the diagonal is s\u221a2, so s = 10/\u221a2 = 5\u221a2.",
  "Area = s\u00b2 = (5\u221a2)\u00b2 = 50 square units. (Shortcut: area = diagonal\u00b2/2 = 100/2 = 50.)",
  "Centre of the square = midpoint of PR = ((-3 + 5)/2, (2 - 4)/2) = (1, -1).",
  "Half-diagonal vector from centre to R is (5 - 1, -4 - (-1)) = (4, -3). To build the other diagonal, swap the components and flip one sign: (3, 4).",
  "Other corners: centre + (3, 4) = (4, 3) and centre - (3, 4) = (-2, -5).",
  "Verify: Q(4, 3) to P(-3, 2): \u221a(7\u00b2 + 1) = \u221a50 = 5\u221a2 (a side). Q to R(5, -4): \u221a(1 + 49) = \u221a50 (a side). Q to S(-2, -5): \u221a(36 + 64) = 10 (the other diagonal). All consistent.",
 ],
 "why": ["The swap-and-flip move rotates the half-diagonal by 90 degrees - it is just Pythagoras thinking in vector form, and it is fully verifiable with the distance formula."],
 "hinglish": "Square ka diagonal diya hai toh side = diagonal/\u221a2 = 5\u221a2, area = 50. Baaki do corners nikalne ka tareeka: pehle centre (midpoint) lo - (1, -1). Half-diagonal (4, -3) hai. Uske components SWAP karo aur ek sign flip karo: (3, 4) ban jayega - ye 90 degree ghuma hua half-diagonal hai. Centre mein plus-minus lagao: (4, 3) aur (-2, -5). Phir verification: sab sides 5\u221a2, doosra diagonal 10. Ye wala question HOTS-zone ka gateway hai - rotation ka idea samajh gaye toh aage Olympiad-level coordinate proofs easy lagenge.",
 "answer": "Diagonal = 10; side = 5\u221a2; area = 50 sq units; other corners Q(4, 3) and S(-2, -5)."}),

("q", {"n": 35, "level": "High", "concept": "Collinearity - negative coordinates (T9)",
 "stem": "Check, without plotting, whether the points (-2, -1), (0, 0) and (4, 3) lie on one straight line. Show your exact arithmetic.",
 "steps": [
  "Given: three points with negative coordinates. Needed: collinearity verdict with exact values.",
  "d1 = distance from (-2, -1) to (0, 0) = \u221a(2\u00b2 + 1\u00b2) = \u221a5.",
  "d2 = distance from (0, 0) to (4, 3) = \u221a(16 + 9) = \u221a25 = 5.",
  "d3 = distance from (-2, -1) to (4, 3) = \u221a(6\u00b2 + 4\u00b2) = \u221a(36 + 16) = \u221a52 = 2\u221a13.",
  "Collinearity requires the largest to equal the sum of the other two: is 2\u221a13 = \u221a5 + 5?",
  "Compare squares of both sides: left squared is 52. Right squared is (\u221a5 + 5)\u00b2 = 5 + 25 + 10\u221a5 = 30 + 10\u221a5 approx 30 + 22.36 = 52.36.",
  "Since 52 differs from 30 + 10\u221a5 (equivalently \u221a5 + 5 approx 7.236 while 2\u221a13 approx 7.211), the equality FAILS.",
  "So the three points are NOT collinear - the middle point sits slightly off the line through the outer two.",
 ],
 "why": ["When radicals are involved, compare by squaring (both sides positive) rather than by decimals - decimals can mislead near-miss cases."],
 "hinglish": "Negative coordinates aane par bhi process same hai. Yahan twist ye hai ki distances roots mein hain - \u221a5, 5, 2\u221a13. Comparison exact karo: dono side ko square karo. Left 52, right 30 + 10\u221a5 approx 52.36. Thoda sa difference hai - matlab NOT collinear. Ye question isliye rakha hai ki tum consider karo ki values kabhi approximate judge na karo. Agar maine jaldi mein 7.24 vs 7.21 dekh ke 'barabar hai' bol diya hota, toh galat ho jaata!",
 "answer": "Not collinear: \u221a5 + 5 is not equal to 2\u221a13 (52 is not equal to 30 + 10\u221a5)."}),

("q", {"n": 36, "level": "High", "concept": "Applied screen/circle problem (T11/T10)",
 "stem": "A computer screen is a rectangle 800 pixels wide and 600 pixels high, with the origin at the bottom-left corner. A circular icon of radius 80 has centre A(100, 150); another of radius 100 has centre B(250, 230). (i) Does any part of either icon stick out of the screen? (ii) Do the two icons overlap each other?",
 "steps": [
  "Given: screen 800 x 600, two circles with centres and radii. Needed: boundary check and overlap check.",
  "Icon A: leftmost x = 100 - 80 = 20 (inside, positive), rightmost x = 100 + 80 = 180 (inside, below 800), lowest y = 150 - 80 = 70 (inside), highest y = 150 + 80 = 230 (inside, below 600). Icon A is fully on the screen.",
  "Icon B: leftmost x = 250 - 100 = 150, rightmost = 250 + 100 = 350, lowest y = 230 - 100 = 130, highest y = 330. All within 0 to 800 and 0 to 600. Fully on screen too.",
  "Overlap test for two circles: compare the centre distance d with r1 + r2 and |r1 - r2|.",
  "Centre distance AB = \u221a((250 - 100)\u00b2 + (230 - 150)\u00b2) = \u221a(150\u00b2 + 80\u00b2) = \u221a(22500 + 6400) = \u221a28900 = 170 (the 8-15-17 triple scaled by 10).",
  "Now r1 + r2 = 180 and |r1 - r2| = 20. Since 20 is less than 170 and 170 is less than 180, the circles intersect in two points - they overlap partially.",
  "So: no icon leaves the screen, and the icons DO overlap.",
 ],
 "hinglish": "Screen check: har icon ka extreme left/right/top/bottom compute karo aur 0-800, 0-600 range se compare karo. Dono andar hain. Overlap ka test yaad rakho: centres ki doori vs radii ka sum. Distance 170 nikla (8-15-17 triple x 10!). 170 < 180 isliye overlap hota hai, aur 170 > 20 isliye poora ek doosre ke andar nahi hai - partial overlap. Ye 2-line test high-school geometry ka swiss knife hai.",
 "answer": "(i) Both icons lie fully inside the screen. (ii) Yes, the icons overlap: AB = 170 lies strictly between |100 - 80| = 20 and 80 + 100 = 180."}),

("q", {"n": 37, "level": "High", "concept": "Locus: equidistant from both axes (T14)",
 "stem": "Describe the set of all points that are equidistant from the x-axis and the y-axis. If such a point must also lie at distance 5 from the origin, list ALL points that satisfy both conditions (exact values).",
 "steps": [
  "Given: equidistant from both axes, then distance-5 filter. Needed: locus, then exact points.",
  "Distance from the x-axis is |y|; distance from the y-axis is |x|. Equality |x| = |y| means y = x or y = -x.",
  "So the locus is the pair of lines y = x and y = -x (the two diagonals through the origin).",
  "Now add: \u221a(x\u00b2 + y\u00b2) = 5. On the line y = x this becomes \u221a(2x\u00b2) = \u221a2 |x| = 5, so |x| = 5/\u221a2 = (5\u221a2)/2.",
  "That gives two points: ((5\u221a2)/2, (5\u221a2)/2) and (-(5\u221a2)/2, -(5\u221a2)/2).",
  "On the line y = -x the same computation gives ((5\u221a2)/2, -(5\u221a2)/2) and (-(5\u221a2)/2, (5\u221a2)/2).",
  "Total: four points, one in each quadrant, all at distance 5 from O and equidistant from both axes. Verify one: ((5\u221a2)/2)\u00b2 + ((5\u221a2)/2)\u00b2 = 25/2 + 25/2 = 25, distance 5. Correct.",
 ],
 "hinglish": "Dono axis se barabar door = |x| = |y| = do diagonal lines y = x aur y = -x. Ab distance 5 bhi chahiye: \u221a(x\u00b2 + y\u00b2) = 5. y = x rakhne par 2x\u00b2 = 25, x = 5/\u221a2 = 5\u221a2/2. Rationalise kar dena toh aur saaf dikhta hai. Chaar points bane - har quadrant mein ek, sab circle (radius 5) par aur dono diagonals par. Locus thinking + circle membership ka combo - yahi HOTS ka taste hai.",
 "answer": "Locus: the two lines y = x and y = -x. The four points are (plus/minus 5\u221a2/2, plus/minus 5\u221a2/2) with matching signs on y = x and opposite signs on y = -x."}),

("q", {"n": 38, "level": "High", "concept": "Triple spotting at scale (T4/T12)",
 "stem": "A triangle has vertices (0, 0), (5, 0) and (0, 12). Identify the right angle, find all three sides, and compute the area and the perimeter. Then state the general rule for a right triangle with legs a and b.",
 "steps": [
  "Given: vertices on both axes. Needed: sides, area, perimeter, general rule.",
  "The side from (0, 0) to (5, 0) lies on the x-axis (length 5); the side from (0, 0) to (0, 12) lies on the y-axis (length 12).",
  "These two axis lines are perpendicular, so the right angle is at the origin.",
  "Hypotenuse = \u221a(5\u00b2 + 12\u00b2) = \u221a(25 + 144) = \u221a169 = 13 (the 5-12-13 triple).",
  "Area = (1/2) x 5 x 12 = 30 square units.",
  "Perimeter = 5 + 12 + 13 = 30 units. Again area equals perimeter - these triple-based triangles love that coincidence.",
  "General rule: for a right triangle with legs a and b, hypotenuse = \u221a(a\u00b2 + b\u00b2), area = ab/2.",
 ],
 "hinglish": "5-12-13 triple ka full Dabangg avatar: area bhi 30, perimeter bhi 30. Chhota triangle 3-4-5 ka bhi area 6 aur perimeter 12 tha - wahan match nahi tha, par 5-12-13 aur 6-8-10 mein area = perimeter nikalta hai (8-6-10: area 24, perimeter 24). Aisi patterns notice karna maths ko interesting banata hai. General rule likhna zaroori hai - examiner ko dikhta hai ki tum case se general tak soch rahe ho.",
 "answer": "Right angle at the origin; sides 5, 12, 13; area = 30 sq units; perimeter = 30 units; general: hypotenuse \u221a(a\u00b2 + b\u00b2), area ab/2."}),

("q", {"n": 39, "level": "High", "concept": "Rectangle verification kit (T6)",
 "stem": "K(1, 1), L(5, 1), M(5, 4) and N(1, 4) are joined in order. Using distances only, prove the figure is a rectangle, and find its perimeter, area and the length of each diagonal.",
 "steps": [
  "Given: four points in cyclic order. Needed: prove rectangle; perimeter, area, diagonals.",
  "KL: y fixed at 1, length |5 - 1| = 4 (horizontal).",
  "LM: x fixed at 5, length |4 - 1| = 3 (vertical).",
  "MN: y fixed at 4, length |5 - 1| = 4 (horizontal). NK: x fixed at 1, length |4 - 1| = 3 (vertical).",
  "Opposite sides are equal, and every side is axis-parallel, so adjacent sides meet at right angles: the figure is a rectangle.",
  "Diagonals: KM = \u221a((5 - 1)\u00b2 + (4 - 1)\u00b2) = \u221a(16 + 9) = \u221a25 = 5. LN = \u221a((1 - 5)\u00b2 + (4 - 1)\u00b2) = \u221a(16 + 9) = 5. Equal diagonals confirm the rectangle property.",
  "Perimeter = 2(4 + 3) = 14 units. Area = 4 x 3 = 12 square units. Both diagonals are 5.",
 ],
 "hinglish": "Ye question rectangle-proof ka full kit hai: (1) opposite sides barabar, (2) sab sides axis-parallel toh right angles automatic, (3) diagonals barabar - teeno checks ho gaye. 3-4-5 triple yahan diagonals mein chhupa hai! Perimeter 14, area 12, diagonal 5. Aise structured answers examiner ko bahut pasand aate hain kyunki har property alag line par verified hai.",
 "answer": "It is a rectangle (equal opposite sides, axis-parallel sides, equal diagonals of length 5); perimeter 14 units, area 12 sq units."}),

("q", {"n": 40, "level": "High", "concept": "Quadrant-restricted distances (T1/T4)",
 "stem": "A point P lies in Quadrant II. Its perpendicular distance from the x-axis is 5 and from the y-axis is 3. Write the coordinates of P and find its distance from the origin. If a twin point P' in Quadrant I has the same axis distances, what is the length PP'?",
 "steps": [
  "Given: Quadrant II point with axis distances 5 (from x-axis) and 3 (from y-axis). Needed: P, OP, and PP'.",
  "Distance from the x-axis is the size of the y-coordinate: |y| = 5. Distance from the y-axis is |x| = 3.",
  "Quadrant II means x negative, y positive. So x = -3 and y = +5, giving P(-3, 5).",
  "OP = \u221a((-3)\u00b2 + 5\u00b2) = \u221a(9 + 25) = \u221a34.",
  "P' in Quadrant I with the same distances: x = +3, y = +5, so P'(3, 5).",
  "PP' joins (-3, 5) to (3, 5): same y, so PP' = |3 - (-3)| = 6 (horizontal segment).",
  "Note the traps avoided: the distance from the x-axis (5) became the y-coordinate, and the Quadrant II condition fixed both signs.",
 ],
 "why": ["Translating 'distance from the x-axis' into 'absolute y-value' is the key step; students who mix this up put 3 and 5 in the wrong slots."],
 "hinglish": "Sabse pehle translation: x-axis se doori 5 matlab |y| = 5; y-axis se doori 3 matlab |x| = 3. Ab quadrant II ka rule lagao - x negative, y positive: P(-3, 5). OP = \u221a34 (koi triple nahi bana, root form chal raha hai). Quadrant I wala twin (3, 5). Dono ka y same, toh distance sirf x ka gap = 6. Ye question pure sign-discipline ka test hai - ek sign ulta kiya toh poora answer flip.",
 "answer": "P(-3, 5); OP = \u221a34; P'(3, 5); PP' = 6 units."}),

("q", {"n": 41, "level": "HOTS", "concept": "Two intersection points on an axis (T5)",
 "stem": "Find ALL points on the x-axis that lie at distance 10 from the point C(3, -6). Explain geometrically why there must be two answers.",
 "steps": [
  "Given: points (x, 0) at distance 10 from C(3, -6). Needed: all such x.",
  "Distance equation: \u221a((x - 3)\u00b2 + (0 - (-6))\u00b2) = 10.",
  "Square both sides: (x - 3)\u00b2 + 36 = 100.",
  "So (x - 3)\u00b2 = 64, giving x - 3 = 8 or x - 3 = -8.",
  "Thus x = 11 or x = -5. The points are (11, 0) and (-5, 0).",
  "Verify: from (11, 0) to (3, -6): \u221a(64 + 36) = \u221a100 = 10. From (-5, 0) to (3, -6): \u221a(64 + 36) = 10. Both valid.",
  "Geometry: a circle of radius 10 centred at C(3, -6) cuts the x-axis at exactly two points because the centre sits 6 units above the axis, which is less than the radius 10 - the circle dips below the axis on both sides of x = 3.",
 ],
 "why": ["The equation (x - 3)\u00b2 = 64 is a disguised two-case problem; the geometric picture (circle cutting a line) tells you in advance how many answers to expect."],
 "hinglish": "Circle-axis ka milaap socho: C se radius 10 ka circle banao, wo x-axis ko kata kyun? Kyunki C axis se sirf 6 door hai aur radius 10 hai - circle axis ke paar niche tak jaata hai, dono taraf se cut karta hai. Equation mein bhi wahi dikh raha hai: (x-3)\u00b2 = 64 ke do roots: x = 11 aur x = -5. Jab bhi square = positive number dikhe, do answers ready rakho. Aur agar centre axis se doori radius se ZYADA hoti, toh zero answers aate - wo case bhi soch ke dekho!",
 "answer": "(11, 0) and (-5, 0); two answers because the circle of radius 10 around C(3, -6) crosses the x-axis twice."}),

("q", {"n": 42, "level": "HOTS", "concept": "Circumcentre discovery (T10/T14)",
 "stem": "For the right triangle with vertices A(0, 0), B(8, 0) and C(8, 6), find the point that is equidistant from all three vertices. Where does it sit, and what pattern do you notice?",
 "steps": [
  "Given: right triangle with legs on the axes... (adapted: right angle at B since AB is horizontal and BC is vertical). Needed: the common-equidistance point.",
  "AB = 8 (horizontal), BC = 6 (vertical), so the right angle is at B(8, 0), and AC is the hypotenuse.",
  "AC = \u221a((8 - 0)\u00b2 + (6 - 0)\u00b2) = \u221a(64 + 36) = \u221a100 = 10.",
  "Claim: the midpoint of the hypotenuse is equidistant from all three vertices. Midpoint M of AC = ((0 + 8)/2, (0 + 6)/2) = (4, 3).",
  "Check MA = \u221a(4\u00b2 + 3\u00b2) = 5. MC = \u221a((8 - 4)\u00b2 + (6 - 3)\u00b2) = \u221a(16 + 9) = 5.",
  "MB = \u221a((8 - 4)\u00b2 + (0 - 3)\u00b2) = \u221a(16 + 9) = 5. All three distances are 5 - verified.",
  "Pattern: in a right triangle, the midpoint of the hypotenuse is equidistant from all three vertices (it is the centre of the circle passing through the three corners). This is the coordinate-proof version of a famous theorem.",
 ],
 "hinglish": "Ye question ek theorem khud discover karwa raha hai! Right angle B par hai (horizontal + vertical legs), hypotenuse AC = 10. Uska midpoint (4, 3) lo - teeno vertices se distance 5, 5, 5. Matlab: right triangle mein hypotenuse ka midpoint hi wo magical point hai jo teeno corners se barabar door baithta hai (circumcentre). 3-4-5 triple yahan bhi kaam kar gaya. Ye result yaad rakho - contest maths mein baar-baar kaam aayega.",
 "answer": "M(4, 3), the midpoint of the hypotenuse, is equidistant (distance 5) from all three vertices."}),

("q", {"n": 43, "level": "HOTS", "concept": "Sum-of-distances locus (T14)",
 "stem": "A(-4, 0) and B(4, 0) are two fixed points. P(0, y) lies on the y-axis such that PA + PB = 10. Find all possible y. Why is y = 0 NOT a solution?",
 "steps": [
  "Given: PA + PB = 10 with P on the y-axis. Needed: y values.",
  "PA = \u221a((0 + 4)\u00b2 + y\u00b2) = \u221a(16 + y\u00b2). By symmetry PB has the same value \u221a(16 + y\u00b2).",
  "So the condition reads 2\u221a(16 + y\u00b2) = 10, hence \u221a(16 + y\u00b2) = 5.",
  "Square: 16 + y\u00b2 = 25, so y\u00b2 = 9, giving y = 3 or y = -3.",
  "Verify y = 3: PA = \u221a(16 + 9) = 5, PB = 5, total 10. Same for y = -3. Both work.",
  "Why not y = 0: then PA = PB = 4 and the sum is 8, which is short of 10 - P at the origin sits strictly between A and B, so PA + PB just equals AB = 8, the minimum possible value. To reach 10 the point must climb off the line.",
 ],
 "hinglish": "Symmetry dekho: A aur B origin ke dono taraf barabar door hain, isliye PA = PB hoga hi. Toh 2 x distance = 10, distance = 5. 16 + y\u00b2 = 25 se y = plus-minus 3. Aur y = 0 kyun nahi: origin par P ke paas PA + PB = AB hi hota hai = 8 - shortest possible. 10 chahiye toh P ko upar ya neeche jhukna padega (y = 3 ya -3). Ye question aage ke classes mein ellipse ka darwaza hai - PA + PB constant wala idea.",
 "answer": "y = 3 or y = -3; y = 0 fails because PA + PB = AB = 8 there, the minimum, not 10."}),

("q", {"n": 44, "level": "HOTS", "concept": "Box method for area (T12/T14)",
 "stem": "A triangle has vertices A(0, 0), B(1, 2) and C(3, 1). Show that it is isosceles, and find its area using the box (enclosing rectangle) method.",
 "steps": [
  "Given: three lattice points. Needed: isosceles proof and area.",
  "AB = \u221a(1\u00b2 + 2\u00b2) = \u221a5. BC = \u221a((3 - 1)\u00b2 + (1 - 2)\u00b2) = \u221a(4 + 1) = \u221a5. AC = \u221a(3\u00b2 + 1\u00b2) = \u221a10.",
  "AB = BC = \u221a5, so the triangle is isosceles (apex at B).",
  "Box method: enclose the triangle in the smallest axis-aligned rectangle: corners (0, 0), (3, 0), (3, 2), (0, 2). Box area = 3 x 2 = 6.",
  "The box minus the triangle leaves three right triangles: T1 below AB with legs 1 and 2 (area 1), T2 right of BC with legs 2 and 1 (area 1), T3 above AC with legs 3 and 1 (area 1.5).",
  "Area of ABC = 6 - 1 - 1 - 1.5 = 2.5 square units.",
  "Cross-check by another triangle with same side data is not needed; instead sanity-check magnitude: the triangle fits inside a 3 x 2 box, so 2.5 is plausible.",
 ],
 "why": ["When the triangle is not right-angled and the base-height pair is not obvious, the box method computes area using only right triangles - fully within Chapter 1 tools."],
 "hinglish": "Jab triangle tedha ho aur base-height na dikhe, box method use karo: triangle ko chhote rectangle mein band karo, rectangle ka area lo, aur charo taraf ke right triangles ghata do. 6 - 1 - 1 - 1.5 = 2.5. Ye technique squares ke root wale triangles ka area nikalne ka desi jugaad hai - bina kisi naye formula ke. Aur dekho, AB = BC = \u221a5 se isosceles bhi proof ho gaya. Do kaam ek question mein.",
 "answer": "Isosceles (AB = BC = \u221a5); area = 2.5 square units via the box method."}),

("q", {"n": 45, "level": "HOTS", "concept": "Chord comparison on a circle (T10/T4)",
 "stem": "Three points A(3, 4), B(-4, 3) and C(0, -5) all lie on the circle of radius 5 centred at the origin (verify this). Find the lengths of the chords AB, BC and CA, and state which chord is the longest.",
 "steps": [
  "Given: three points, circle radius 5. Needed: verify membership, three chord lengths, longest chord.",
  "Membership: A: 9 + 16 = 25. B: 16 + 9 = 25. C: 0 + 25 = 25. All equal to r\u00b2 = 25, so all three lie on the circle.",
  "AB = \u221a((-4 - 3)\u00b2 + (3 - 4)\u00b2) = \u221a(49 + 1) = \u221a50 = 5\u221a2 (approximately 7.07).",
  "BC = \u221a((0 + 4)\u00b2 + (-5 - 3)\u00b2) = \u221a(16 + 64) = \u221a80 = 4\u221a5 (approximately 8.94).",
  "CA = \u221a((3 - 0)\u00b2 + (4 + 5)\u00b2) = \u221a(9 + 81) = \u221a90 = 3\u221a10 (approximately 9.49).",
  "Comparing exact squares: 90 > 80 > 50, so CA > BC > AB.",
  "The longest chord is CA with length 3\u221a10. (No chord can exceed the diameter 10, and indeed all three are below 10.)",
 ],
 "hinglish": "Pehle membership - teeno 25 de rahe hain, sab circle par. Phir chords: \u221a50, \u221a80, \u221a90. Compare karne ka clean tareeka: squares compare karo (50 < 80 < 90), roots ki zaroorat nahi. Longest CA = 3\u221a10 approx 9.49. Aur ek boundary-check: diameter 10 hai, koi chord 10 se bada nahi - hamara answer us limit ke andar hi hai. Yahi internal consistency marks dilati hai.",
 "answer": "All three lie on the circle; AB = 5\u221a2, BC = 4\u221a5, CA = 3\u221a10; the longest chord is CA."}),

("q", {"n": 46, "level": "HOTS", "concept": "Parallelogram via diagonal midpoints (T8/T6)",
 "stem": "A(1, 2), B(4, 3) and C(6, 7) are three vertices of parallelogram ABCD taken in order. Find the fourth vertex D using the fact that the diagonals of a parallelogram bisect each other, and verify your answer.",
 "steps": [
  "Given: three consecutive vertices of a parallelogram. Needed: D.",
  "Diagonals of a parallelogram bisect each other, so midpoint of AC must equal midpoint of BD.",
  "Midpoint of AC = ((1 + 6)/2, (2 + 7)/2) = (3.5, 4.5).",
  "Let D = (x, y). Midpoint of BD = ((4 + x)/2, (3 + y)/2). Set equal to (3.5, 4.5).",
  "From x: (4 + x)/2 = 3.5 gives x = 3. From y: (3 + y)/2 = 4.5 gives y = 6.",
  "So D = (3, 6).",
  "Verify as a parallelogram by sides: AB = \u221a(3\u00b2 + 1\u00b2) = \u221a10, DC = \u221a((6 - 3)\u00b2 + (7 - 6)\u00b2) = \u221a(9 + 1) = \u221a10; BC = \u221a(2\u00b2 + 4\u00b2) = \u221a20 = 2\u221a5, AD = \u221a((3 - 1)\u00b2 + (6 - 2)\u00b2) = \u221a(4 + 16) = \u221a20. Opposite sides equal - consistent.",
 ],
 "why": ["The diagonal-midpoint method converts a geometry condition into two tiny linear equations - far safer than guessing a translation vector."],
 "hinglish": "Parallelogram ka chautha vertex nikalne ka RULE: diagonals ka midpoint same hota hai. AC ka midpoint lo, phir BD ka midpoint uske barabar rakho - do chhote equations mil gaye: x = 3, y = 6. Verification mein opposite sides bhi barabar nikli (\u221a10 aur 2\u221a5 ke pairs). Ye midpoint-trick Q31 (trisection) ke saath milke midpoint-based toolkit complete karta hai: aage class 10 mein yehi idea hi midpoint formula ka base banega.",
 "answer": "D = (3, 6); verified since AB = DC = \u221a10 and BC = AD = 2\u221a5."}),

("q", {"n": 47, "level": "HOTS", "concept": "Grid-walk vs direct distance (T11/T4)",
 "stem": "A delivery robot moves on a grid of unit squares. It must travel from station S(1, 1) to station T(7, 4). (i) What is the length of the shortest path using only horizontal and vertical moves? (ii) What is the straight-line distance? (iii) A second robot flies directly. How much distance does it save compared to the ground robot?",
 "steps": [
  "Given: grid unit 1, S(1, 1) to T(7, 4). Needed: street length, direct length, saving.",
  "Horizontal gap = 7 - 1 = 6 units; vertical gap = 4 - 1 = 3 units.",
  "Ground robot (only axis moves): 6 + 3 = 9 units. Every such path has exactly this length - no order of moves can beat it.",
  "Flying robot (straight line): \u221a(6\u00b2 + 3\u00b2) = \u221a(36 + 9) = \u221a45 = 3\u221a5 (approximately 6.71 units).",
  "Saving = 9 - 3\u221a5 (exactly), approximately 9 - 6.71 = 2.29 units.",
  "Keep the exact answer 9 - 3\u221a5 in the final statement; the decimal is only for intuition.",
 ],
 "hinglish": "Grid-walk ka funda: horizontal steps + vertical steps hamesha fix hote hain (yahan 6 + 3 = 9), chahe kisi bhi order mein chalo. Direct distance Pythagoras se 3\u221a5. Saving 9 - 3\u221a5 approx 2.3 units. Ye question Q26 (city auto) ka bhai hai - wahan 200 m blocks the, yahan 1 unit. Same skeleton, naye numbers - yahi 'question structure' samajhna original practice hai, ratna nahi.",
 "answer": "(i) 9 units   (ii) 3\u221a5 units (approx 6.71)   (iii) saving 9 - 3\u221a5 approx 2.29 units."}),

("q", {"n": 48, "level": "HOTS", "concept": "Equally spaced collinear chain (T9/T8)",
 "stem": "P(1, 2), Q(4, 6) and R(7, 10) are three points. Show they are collinear and equally spaced. Then find the point T on the same line, beyond R, with QT = 10.",
 "steps": [
  "Given: three points. Needed: collinearity, equal spacing, then T.",
  "PQ = \u221a((4 - 1)\u00b2 + (6 - 2)\u00b2) = \u221a(9 + 16) = 5.",
  "QR = \u221a((7 - 4)\u00b2 + (10 - 6)\u00b2) = \u221a(9 + 16) = 5.",
  "PR = \u221a((7 - 1)\u00b2 + (10 - 2)\u00b2) = \u221a(36 + 64) = 10.",
  "Since PR = PQ + QR = 10, the points are collinear, and PQ = QR = 5 shows Q is exactly the midpoint - equally spaced.",
  "The repeated step from P to Q is (+3, +4). The same step continues from Q to R, and one more step lands at T = (7 + 3, 10 + 4) = (10, 14).",
  "Check QT: from Q(4, 6) to T(10, 14) is two steps: 2 x 5 = 10. Verified.",
 ],
 "why": ["A constant coordinate-step (+3, +4) between consecutive points is the signature of equal spacing on a line - recognise the pattern and distances become trivial."],
 "hinglish": "Pattern-spotting question! Har agle point mein (+3, +4) jud raha hai - 3-4-5 triple ka repeated use. PQ = QR = 5, PR = 10: collinear + equally spaced confirmed. Ab 'beyond R with QT = 10' ka matlab: Q se 2 step aage = R se 1 step aage = T(10, 14). Verify kiya QT = 10. Aise 'chain' questions mein step-pakadna hi asli skill hai, har baar distance formula chalana nahi.",
 "answer": "Collinear with PQ = QR = 5, PR = 10; T = (10, 14) with QT = 10 verified."}),

("q", {"n": 49, "level": "HOTS", "concept": "Chord and centre distance (T10/T8)",
 "stem": "A circle of radius 10 is centred at the origin. A and B(−8, 6) are two points on it, with A(6, 8). Find the length of chord AB and the perpendicular distance of the chord from the centre. Verify the right-triangle relation between them.",
 "steps": [
  "Given: circle x\u00b2 + y\u00b2 = 100, chord joining A(6, 8) and B(-8, 6). Needed: chord length, distance from centre, consistency check.",
  "First confirm membership: A: 36 + 64 = 100. B: 64 + 36 = 100. Both on the circle.",
  "Chord AB = \u221a((-8 - 6)\u00b2 + (6 - 8)\u00b2) = \u221a(196 + 4) = \u221a200 = 10\u221a2.",
  "Midpoint M of the chord = ((6 + (-8))/2, (8 + 6)/2) = (-1, 7).",
  "The line from the centre to the midpoint of a chord is perpendicular to the chord, so the required distance is OM = \u221a((-1)\u00b2 + 7\u00b2) = \u221a50 = 5\u221a2.",
  "Right-triangle check: half-chord = 5\u221a2, OM = 5\u221a2, radius = 10. Indeed (5\u221a2)\u00b2 + (5\u221a2)\u00b2 = 50 + 50 = 100 = 10\u00b2.",
  "Everything is consistent - the chord, its distance from the centre and the radius obey the Baudhayana-Pythagoras relation.",
 ],
 "hinglish": "Do kaam ek saath: chord length (distance formula se 10\u221a2) aur centre se doori. Fundaa: chord ke midpoint se centre ko jodo - wo line chord par perpendicular hoti hai, toh wahi distance hai. OM = \u221a50 = 5\u221a2. Phir master-check: (half-chord)\u00b2 + (distance)\u00b2 = radius\u00b2. 50 + 50 = 100. Perfect. Ye relation har circle-chord question ka backbone hai - yahin se 'perpendicular from centre bisects chord' wali theory aati hai.",
 "answer": "AB = 10\u221a2; distance from centre = 5\u221a2; verified since (5\u221a2)\u00b2 + (5\u221a2)\u00b2 = 100 = radius\u00b2."}),

("q", {"n": 50, "level": "HOTS", "concept": "Full square proof chain (T14)",
 "stem": "Prove that the points P(1, 7), Q(4, 2), R(-1, -1) and S(-4, 4), taken in this order, are the vertices of a square. You must verify ALL necessary properties using the distance formula and midpoints.",
 "steps": [
  "Given: four points in cyclic order. Needed: full square proof.",
  "PQ = \u221a((4 - 1)\u00b2 + (2 - 7)\u00b2) = \u221a(9 + 25) = \u221a34.",
  "QR = \u221a((-1 - 4)\u00b2 + (-1 - 2)\u00b2) = \u221a(25 + 9) = \u221a34.",
  "RS = \u221a((-4 + 1)\u00b2 + (4 + 1)\u00b2) = \u221a(9 + 25) = \u221a34.",
  "SP = \u221a((1 + 4)\u00b2 + (7 - 4)\u00b2) = \u221a(25 + 9) = \u221a34. All four sides equal: it is at least a rhombus-shaped candidate.",
  "Diagonals: PR = \u221a((-1 - 1)\u00b2 + (-1 - 7)\u00b2) = \u221a(4 + 64) = \u221a68 = 2\u221a17. QS = \u221a((-4 - 4)\u00b2 + (4 - 2)\u00b2) = \u221a(64 + 4) = \u221a68. Diagonals are equal.",
  "Bisecting check: midpoint of PR = ((1 + (-1))/2, (7 + (-1))/2) = (0, 3). Midpoint of QS = ((4 + (-4))/2, (2 + 4)/2) = (0, 3). Diagonals bisect each other, so the figure is a parallelogram.",
  "A parallelogram with all sides equal is a rhombus; a rhombus with equal diagonals is a square. Hence PQRS is a square.",
  "Optional right-angle cross-check: PR\u00b2 = 68 and PQ\u00b2 + QR\u00b2 = 34 + 34 = 68, so the angle at Q (opposite diagonal PR) is 90 degrees by the converse of Pythagoras.",
 ],
 "why": ["The clean chain for proving a square with distances only: sides equal (rhombus candidate) + diagonals bisect (parallelogram) + diagonals equal (square). Each link uses only Chapter 1 tools."],
 "hinglish": "Ye Chapter 1 ka final boss hai. Strategy 3-layer ki hai: (1) chaaron sides \u221a34 - rhombus material, (2) diagonals ke midpoints dono (0, 3) - parallelogram confirm, (3) diagonals dono \u221a68 - square confirm. Bonus check: 68 = 34 + 34 se right angle bhi mil gaya. Notice karo kitna systematic hai - 'sides equal + diagonals bisect + diagonals equal' ye teen-step recipe kisi bhi square-proof question mein chalegi. Ye last question mein jaan-bujh ke negative coordinates aur non-axis orientation rakha hai taaki tum axes par dependent na raho.",
 "answer": "PQRS is a square: all sides \u221a34, diagonals equal (2\u221a17) and bisecting each other at (0, 3), with right angles confirmed by 68 = 34 + 34."}),
]
